namespace Jellyfin.Plugin.AutomaticDeletionRequests;

public sealed record MetadataField(string Id,string Source,string Label,string Type,string[] Operators,string? Unit=null);
public static class MetadataCatalog
{
    public static readonly string[] Sources=["jellyfin","seerr","sonarr","radarr"];
    public static string[] Operators(string type) => [..ValueOperators(type),"exists","not-exists"];
    private static string[] ValueOperators(string type)=>type switch {
        "boolean" or "user" => ["equals","not-equals"],
        "text" => ["equals","not-equals","contains","not-contains"],
        "list" => ["contains","not-contains","contains-partial","not-contains-partial","contains-any","contains-all","not-contains-all","contains-none","count-equals","count-not-equals","count-greater","count-less"],
        "date" => ["before","after","equals","not-equals","older-days","newer-days","older-hours","newer-hours","in-last-days","in-next-days"],
        _ => ["equals","not-equals","greater","less"]
    };
    public static readonly MetadataField[] Fields=Build().ToArray();
    public static MetadataField? Find(string id)=>Fields.FirstOrDefault(f=>f.Id==id);
    private static IEnumerable<MetadataField> Build() {
        MetadataField F(string id,string source,string label,string type,string? unit=null)=>new(id,source,label,type,Operators(type),unit);
        foreach(var f in new[]{F("title","jellyfin","Title","text"),F("year","jellyfin","Release year","number"),F("added","jellyfin","Added","date"),F("rating","jellyfin","Audience rating","number"),F("kind","jellyfin","Media kind","text"),
            F("seerr.ownRequest","seerr","Owned by authorizer (legacy)","boolean"),F("seerr.is4k","seerr","4K edition","boolean"),F("seerr.requestOnly","seerr","Unfulfilled request","boolean"),F("seerr.requesterId","seerr","Requester Jellyfin user ID","user")})yield return f;
        foreach(var (id,label,type) in new (string,string,string)[]{("genres","Genres","list"),("tags","Tags","list"),("studios","Studios","list"),("officialRating","Content rating","text"),("criticRating","Critic rating","number"),("premiereDate","Release date","date"),("runtimeMinutes","Runtime","number"),("endDate","Ended on","date"),("productionLocations","Production locations","list"),("originalTitle","Original title","text")})yield return F("jellyfin."+id,"jellyfin",label,type,id=="runtimeMinutes"?"minutes":null);
        foreach(var (id,label,type) in new (string,string,string)[]{("seenBy","Watched by (Jellyfin IDs)","list"),("favoritedBy","Favourited by (Jellyfin IDs)","list"),("playCount","Total play count","number"),("lastPlayedAt","Last played","date"),("episodeCount","Episodes","number"),("viewedEpisodes","Episodes watched by anyone","number"),("allEpisodesSeenBy","All episodes watched by (Jellyfin IDs)","list"),("watchers","Episode watchers (Jellyfin IDs)","list"),("lastEpisodeAdded","Latest episode added","date"),("lastEpisodeAired","Latest episode aired","date")})yield return F("jellyfin."+id,"jellyfin",label,type);
        foreach(var (id,label,type) in new (string,string,string)[]{("actors","Actors","list"),("directors","Directors","list"),("writers","Writers","list"),("people","People","list"),("collections","Manual collection names","list"),("collectionIds","Manual collection IDs","list"),("playlists","Manual playlist names","list"),("playlistIds","Manual playlist IDs","list"),("videoCodecs","Video codecs (all files)","list"),("audioCodecs","Audio codecs (all files)","list"),("audioLanguages","Audio languages (all files)","list"),("subtitleLanguages","Subtitle languages (all files)","list"),("videoRanges","Video ranges (all files)","list"),("maxVideoWidth","Maximum video width","number"),("maxVideoHeight","Maximum video height","number"),("maxAudioChannels","Maximum audio channels","number"),("watchedByAll","Watched by every enabled user","boolean"),("unwatchedByAll","Unwatched by every enabled user","boolean"),("partiallyWatchedBy","Partially watched by (Jellyfin IDs)","list"),("resumePositionMinutes","Largest resume position","number"),("tmdbId","TMDb ID","text"),("tvdbId","TVDb ID","text"),("imdbId","IMDb ID","text")})yield return F("jellyfin."+id,"jellyfin",label,type);
        foreach(var (id,label,type)in new (string,string,string)[]{("collectionSiblingSeenBy","Direct manual-collection sibling watchers (Jellyfin IDs)","list"),("collectionSiblingLastPlayedAt","Latest direct manual-collection sibling play","date"),("collectionSiblingPlayCount","Direct manual-collection sibling play count","number")})yield return F("jellyfin."+id,"jellyfin",label,type);
        foreach(var (id,label,type)in new (string,string,string)[]{("lastViewedAt","Latest native timestamp on watched items","date"),("seenSinceAddedBy","Native completed watchers since added (Jellyfin IDs)","list"),("allEpisodesSeenSinceAddedBy","All episodes completed since added (Jellyfin IDs)","list"),("completedWatchCount","Completed native user/item records (not total plays)","number"),("newestWatchedEpisodeAt","Native timestamp of highest-numbered watched episode","date")})yield return F("jellyfin."+id,"jellyfin",label,type);
        foreach(var (id,label,type) in new (string,string,string)[]{("latestSeasonNumber","Latest regular season number","number"),("latestSeasonEpisodeCount","Latest regular season aired episodes","number"),("latestSeasonFileCount","Latest regular season files","number"),("latestSeasonMissingEpisodes","Latest regular season missing episodes","number"),("lastEpisodeAired","Latest episode aired","date"),("nextEpisodeAirs","Next episode airs","date"),("latestSeasonFinaleAired","Latest regular season finale aired","date"),("fileQualityNames","Episode file quality names","list"),("fileVideoCodecs","Episode file video codecs","list"),("fileAudioCodecs","Episode file audio codecs","list"),("fileAudioLanguages","Episode file audio languages","list"),("fileQualityCutoffMet","All episode files meet quality cutoff","boolean"),("latestFileAdded","Latest episode file added","date")})yield return F("sonarr."+id,"sonarr",label,type);
        foreach(var (id,label,type) in new (string,string,string)[]{("requestCount","Request count","number"),("isRequested","Requested","boolean"),("requestDate","First requested","date"),("mediaAddedAt","Media added","date"),("status","Availability status","number"),("requesters","Requester Jellyfin IDs","list")})yield return F("seerr."+id,"seerr",label,type);
        foreach(var source in new[]{"radarr","sonarr"}) {
            foreach(var (id,label,type,unit) in new (string,string,string,string?)[]{("title","Title","text",null),("id","Service ID","number",null),("added","Added","date",null),("path","Path","text",null),("monitored","Monitored","boolean",null),("tags","Tags","list",null),("qualityProfile","Quality profile","text",null),("qualityProfileId","Quality profile ID","number",null),("sizeOnDisk","Size on disk","number","MiB"),("originalLanguage","Original language","text",null),("status","Status","text",null),("runtime","Runtime","number","minutes")})yield return F(source+"."+id,source,label,type,unit);
        }
        foreach(var (id,label,type) in new (string,string,string)[]{("fileAdded","File added","date"),("filePath","File path","text"),("fileQuality","Video resolution","number"),("fileQualityName","File quality","text"),("fileQualityCutoffMet","Quality cutoff met","boolean"),("fileAudioChannels","Audio channels","number"),("fileAudioLanguages","Audio languages","list"),("physicalRelease","Physical release","date"),("digitalRelease","Digital release","date"),("inCinemas","Cinema release","date"),("imdbRating","IMDb rating","number"),("imdbVotes","IMDb votes","number"),("traktRating","Trakt rating","number"),("traktVotes","Trakt votes","number"),("rottenTomatoesRating","Rotten Tomatoes rating","number"),("rottenTomatoesVotes","Rotten Tomatoes votes","number")})yield return F("radarr."+id,"radarr",label,type);
        foreach(var (id,label,type) in new (string,string,string)[]{("ended","Ended","boolean"),("firstAired","First aired","date"),("seriesType","Series type","text"),("seasonCount","Seasons","number"),("monitoredSeasons","Monitored seasons","number"),("episodeCount","Episodes with files","number"),("totalEpisodeCount","Total episodes","number"),("episodeFileCount","Episode files","number"),("missingEpisodes","Missing aired episodes","number"),("unairedEpisodes","Unaired episodes","number"),("rating","Rating","number"),("ratingVotes","Rating votes","number")})yield return F("sonarr."+id,"sonarr",label,type);
    }
}
